//! Rigged peon bodies: one skinned glTF per life stage (`assets/models/peon_*.glb`, generated by
//! `assets/blender/make_peons.py`), posed on the CPU from the sim's [`Posture`] and drawn with the
//! renderer's skinned path. Appearance drives the palette (skin, hair, clothes, eyes), the `slim`/`heavy`
//! morph targets (build), the hair mesh and a height scale.

use std::collections::HashMap;

use glam::{Mat4, Vec3};
use hearth_render::model::{Model, Pose as JointPose};
use hearth_render::{PALETTE_SLOTS, Renderer, SkinnedDraw, SkinnedMeshId};
use sim::components::{Appearance, Personality, Posture};
use sim::Entity;
use sim::data::{Hand, LifeStage, Pose};

/// Palette slots, matched to material names in the glTF files.
pub mod slot {
    pub const SKIN: u32 = 1;
    pub const HAIR: u32 = 2;
    pub const SHIRT: u32 = 3;
    pub const PANTS: u32 = 4;
    pub const SHOES: u32 = 5;
    pub const IRIS: u32 = 6;
}

pub const HAIR_STYLES: usize = 4;
const SHOE_COLOR: [f32; 3] = [0.15, 0.12, 0.1];

fn slot_of(material: &str) -> u32 {
    match material {
        "skin" => slot::SKIN,
        "hair" => slot::HAIR,
        "shirt" => slot::SHIRT,
        "pants" => slot::PANTS,
        "shoes" => slot::SHOES,
        "iris" => slot::IRIS,
        _ => 0,
    }
}

macro_rules! glb {
    ($name:literal) => {
        ($name, include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/models/peon_", $name, ".glb")).as_slice())
    };
}
const FILES: [(&str, &[u8]); 6] = [glb!("infant"), glb!("toddler"), glb!("child"), glb!("teen"), glb!("adult"), glb!("elder")];

fn file_index(stage: LifeStage) -> usize {
    match stage {
        LifeStage::Infant => 0,
        LifeStage::Toddler => 1,
        LifeStage::Child => 2,
        LifeStage::Teen => 3,
        LifeStage::YoungAdult | LifeStage::Adult => 4,
        LifeStage::Elder => 5,
    }
}

struct StageArt {
    model: Model,
    body: SkinnedMeshId,
    hair: [Option<SkinnedMeshId>; HAIR_STYLES],
    /// Morph slots of the `slim` and `heavy` targets on the body mesh.
    slim: Option<usize>,
    heavy: Option<usize>,
    /// Rest-pose height of the model and of its head joint (for label placement).
    height: f32,
    head_joint: Option<usize>,
    head_rest_y: f32,
    /// Per hand (right, left): the joint and the grip frame relative to it (see `PropDef`).
    grips: [Option<(usize, Mat4)>; 2],
}

/// The grip frame of a hand in the rest pose, relative to the hand joint: origin in the palm, +y
/// along the bone, +z towards the body's forward (+z) made perpendicular to the bone.
fn grip_offset(skel: &hearth_render::model::Skeleton, joint: usize, height: f32) -> Mat4 {
    let g = skel.globals(&skel.rest_pose())[joint];
    let y = g.y_axis.truncate().normalize();
    let z = (Vec3::Z - y * y.dot(Vec3::Z)).normalize();
    let x = y.cross(z);
    let palm = g.w_axis.truncate() + y * height * 0.035;
    let rest = Mat4::from_cols(x.extend(0.0), y.extend(0.0), z.extend(0.0), palm.extend(1.0));
    g.inverse() * rest
}

/// How a peon carries themselves when not doing anything in particular (idle and walk variants).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Demeanor {
    #[default]
    Normal,
    /// Bad mood: slumped shoulders, dragging feet.
    Sad,
    /// Theatrical or vain and in a good mood: chin up, strutting.
    Proud,
    /// Paranoid: glances over the shoulder.
    Nervous,
}

impl Demeanor {
    pub fn of(mood: f32, p: Option<&Personality>) -> Demeanor {
        let has = |t: &str| p.is_some_and(|p| p.has(t));
        if mood < -35.0 {
            Demeanor::Sad
        } else if has("paranoid") {
            Demeanor::Nervous
        } else if (has("theatrical") || has("vain")) && mood > 15.0 {
            Demeanor::Proud
        } else {
            Demeanor::Normal
        }
    }
}

/// What a drawn body reports back: the height of the crown above the root (for labels), whether
/// it is playing the interaction's own clip, and the world-space grip frame of each hand (right,
/// left) for props.
#[derive(Clone, Copy, Debug)]
pub struct Drawn {
    pub crown: f32,
    pub acting: bool,
    pub grips: [Mat4; 2],
}

impl Drawn {
    /// Where to draw a prop held in `hand`; None when the body fell back to a generic pose clip
    /// (an infant "reading"), whose hands aren't posed to hold anything.
    pub fn grip(&self, hand: Hand) -> Option<Mat4> {
        self.acting.then(|| {
            self.grips[match hand {
                Hand::Right => 0,
                Hand::Left => 1,
            }]
        })
    }
}

/// How to draw a body.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub enum Look {
    #[default]
    Normal,
    /// Translucent, glowing, pale (the dead walking the lot).
    Ghost,
}

pub struct PeonArt {
    stages: Vec<StageArt>,
}

impl PeonArt {
    /// Parses the embedded models and uploads their meshes.
    pub fn load(r: &mut Renderer) -> anyhow::Result<PeonArt> {
        let mut stages = Vec::with_capacity(FILES.len());
        for (name, bytes) in FILES {
            let model = Model::load_glb(bytes, &slot_of).map_err(|e| anyhow::anyhow!("peon_{name}.glb: {e}"))?;
            let body_mesh = model.mesh("body").ok_or_else(|| anyhow::anyhow!("peon_{name}.glb: no body mesh"))?;
            let body = r.upload_skinned_mesh(&body_mesh.data);
            let (slim, heavy) = (body_mesh.morph("slim"), body_mesh.morph("heavy"));
            let mut hair = [None; HAIR_STYLES];
            for (i, h) in hair.iter_mut().enumerate() {
                *h = model.mesh(&format!("hair{i}")).map(|m| r.upload_skinned_mesh(&m.data));
            }
            let height = body_mesh.data.vertices.iter().map(|v| v.pos[1]).fold(0.0, f32::max);
            let head_joint = model.skeleton.joint("head");
            let head_rest_y = head_joint.map_or(height, |j| model.skeleton.globals(&model.skeleton.rest_pose())[j].w_axis.y);
            let grips = ["hand.R", "hand.L"].map(|n| model.skeleton.joint(n).map(|j| (j, grip_offset(&model.skeleton, j, height))));
            stages.push(StageArt { model, body, hair, slim, heavy, height, head_joint, head_rest_y, grips });
        }
        Ok(PeonArt { stages })
    }

    /// Adds a posed body to a frame's `skinned` draws and `joints`. `t` is a per-peon clock in
    /// seconds; `anim` carries the peon's playback between frames (a fresh [`AnimState`] poses it
    /// straight from `t`, with no blending).
    #[allow(clippy::too_many_arguments)]
    pub fn draw(&self, out: (&mut Vec<SkinnedDraw>, &mut Vec<Mat4>), pos: Vec3, yaw: f32, stage: LifeStage, app: &Appearance, posture: &Posture, demeanor: Demeanor, anim: &mut AnimState, t: f32, look: Look) -> Drawn {
        let fi = file_index(stage);
        let art = &self.stages[fi];
        let (clip, rate) = clip_for(&art.model, stage, posture, demeanor, art.height);
        let acting = posture.anim.as_deref() == Some(clip);
        let skel = &art.model.skeleton;
        let (pos, yaw) = anim.update(&art.model, fi, clip, rate, t, pos, yaw);
        let pose = &anim.pose;
        let mut mats = Vec::with_capacity(skel.joints.len());
        skel.skin_matrices(pose, &mut mats);
        let (skinned, joints) = out;
        let pose_id = hearth_render::push_pose(joints, &mats);

        let scale = stage.height() / art.height.max(0.01) * app.height;
        let model = Mat4::from_translation(pos) * Mat4::from_rotation_y(yaw) * Mat4::from_scale(Vec3::splat(scale));
        let mut palette = [[1.0f32; 4]; PALETTE_SLOTS];
        let rgb = |c: [f32; 3]| [c[0], c[1], c[2], 1.0];
        palette[slot::SKIN as usize] = rgb(app.skin);
        palette[slot::HAIR as usize] = rgb(app.hair);
        palette[slot::SHIRT as usize] = rgb(app.shirt);
        palette[slot::PANTS as usize] = rgb(app.pants);
        palette[slot::SHOES as usize] = rgb(SHOE_COLOR);
        palette[slot::IRIS as usize] = rgb(app.eyes);
        let mut morph = [0.0; hearth_render::MAX_MORPHS];
        if let Some(i) = art.slim {
            morph[i] = ((0.5 - app.build) * 2.0).clamp(0.0, 1.0);
        }
        if let Some(i) = art.heavy {
            morph[i] = ((app.build - 0.5) * 2.0).clamp(0.0, 1.0);
        }
        let mut body = SkinnedDraw::new(art.body, pose_id, model, palette);
        body.morph = morph;
        let hair = art.hair[app.hair_style as usize % HAIR_STYLES].map(|h| {
            let mut d = SkinnedDraw::new(h, pose_id, model, palette);
            d.roughness = 0.55;
            d
        });
        for mut d in std::iter::once(body).chain(hair) {
            if look == Look::Ghost {
                for c in &mut d.palette {
                    *c = [c[0] * 0.3 + 0.55, c[1] * 0.3 + 0.7, c[2] * 0.3 + 0.75, 1.0];
                }
                d.color[3] = 0.38;
                d.emissive = 0.6;
                d.flags |= hearth_render::flags::NO_SHADOW_CAST;
            }
            skinned.push(d);
        }

        // top of the head: the head joint's posed height plus its rest distance to the crown
        let globals = skel.globals(pose);
        let head_y = art.head_joint.map_or(art.head_rest_y, |j| globals[j].w_axis.y);
        let crown = if posture.pose == Pose::Lie { head_y + 0.1 } else { head_y + (art.height - art.head_rest_y) };
        let grips = art.grips.map(|g| g.map_or(model, |(j, off)| model * globals[j] * off));
        Drawn { crown: crown * scale, acting, grips }
    }
}

/// Seconds to cross-fade from one clip to the next.
pub const BLEND_SECS: f32 = 0.3;
/// A root jump on a clip change further than this is a teleport (not eased).
const MAX_ROOT_EASE: f32 = 3.0;

/// One peon's animation playback, kept by the game between frames: the clip playing, how far
/// into it, and a cross-fade from the last pose drawn when the clip changes. The fade also eases
/// the root, because the sim snaps a peon onto a seat or bed at the moment its posture changes.
#[derive(Clone, Debug, Default)]
pub struct AnimState {
    /// Body model and clip index playing (None = rest pose); None until the first update.
    playing: Option<(usize, Option<usize>)>,
    /// Seconds into the clip (already scaled by playback rate).
    phase: f32,
    last_t: f32,
    /// Pose faded out from, and fade progress (0..1; 1 = done).
    from: JointPose,
    fade: f32,
    /// Root offset (from the old drawn position/yaw to the new) faded out with the pose.
    root_offset: Vec3,
    yaw_offset: f32,
    last_root: (Vec3, f32),
    /// Last pose produced.
    pub pose: JointPose,
    seen: u64,
}

impl AnimState {
    /// Advances playback to `t` and writes the pose into `self.pose`. Returns the root position
    /// and yaw to draw at (eased during a fade).
    #[allow(clippy::too_many_arguments)]
    pub fn update(&mut self, model: &Model, body: usize, clip: &str, rate: f32, t: f32, pos: Vec3, yaw: f32) -> (Vec3, f32) {
        let skel = &model.skeleton;
        let clip = model.clips.iter().position(|c| c.name == clip);
        match self.playing {
            Some((b, c)) if b == body && self.pose.len() == skel.joints.len() => {
                let dt = (t - self.last_t).clamp(0.0, 0.25);
                if c != clip {
                    self.from.clone_from(&self.pose);
                    self.fade = 0.0;
                    self.phase = 0.0;
                    self.playing = Some((body, clip));
                    let (p0, y0) = self.last_root;
                    let (off, yoff) = (p0 - pos, wrap_angle(y0 - yaw));
                    (self.root_offset, self.yaw_offset) = if off.length() < MAX_ROOT_EASE { (off, yoff) } else { (Vec3::ZERO, 0.0) };
                }
                self.phase += dt * rate;
                self.fade = (self.fade + dt / BLEND_SECS).min(1.0);
            }
            // first frame, or a new body (aged up): start in sync with the clock, no fade
            _ => {
                self.playing = Some((body, clip));
                self.phase = t * rate;
                self.fade = 1.0;
                self.root_offset = Vec3::ZERO;
                self.yaw_offset = 0.0;
            }
        }
        self.last_t = t;

        self.pose.clear();
        self.pose.extend(skel.joints.iter().map(|j| j.rest));
        if let Some(c) = clip {
            model.clips[c].sample(self.phase, &mut self.pose);
        }
        let (pos, yaw) = if self.fade < 1.0 {
            let w = self.fade * self.fade * (3.0 - 2.0 * self.fade);
            for (p, f) in self.pose.iter_mut().zip(&self.from) {
                *p = f.lerp(*p, w);
            }
            (pos + self.root_offset * (1.0 - w), yaw + self.yaw_offset * (1.0 - w))
        } else {
            (pos, yaw)
        };
        self.last_root = (pos, yaw);
        (pos, yaw)
    }
}

fn wrap_angle(a: f32) -> f32 {
    use std::f32::consts::{PI, TAU};
    (a + PI).rem_euclid(TAU) - PI
}

/// Animation state for every peon on screen, keyed by entity. Call [`Animator::begin_frame`] once
/// per frame; peons not drawn in a frame are forgotten (and snap into their pose when next seen).
#[derive(Debug, Default)]
pub struct Animator {
    states: HashMap<Entity, AnimState>,
    frame: u64,
}

impl Animator {
    pub fn begin_frame(&mut self) {
        let f = self.frame;
        self.states.retain(|_, s| s.seen == f);
        self.frame += 1;
    }

    pub fn state(&mut self, e: Entity) -> &mut AnimState {
        let s = self.states.entry(e).or_default();
        s.seen = self.frame;
        s
    }
}

/// Clip name and playback rate for a posture: the interaction's own clip when this body has it,
/// else the pose's (with the demeanor's idle/walk variant). Walk cadence speeds up for shorter legs.
fn clip_for<'a>(model: &Model, stage: LifeStage, posture: &'a Posture, demeanor: Demeanor, model_height: f32) -> (&'a str, f32) {
    if !posture.walking
        && let Some(a) = posture.anim.as_deref()
        && model.clip(a).is_some()
    {
        return (a, 1.0);
    }
    let variant = |base: &'static str| -> &'static str {
        let v = match (demeanor, base) {
            (Demeanor::Sad, "walk") => "walk_sad",
            (Demeanor::Sad, "idle") => "idle_sad",
            (Demeanor::Proud, "walk") => "walk_proud",
            (Demeanor::Proud, "idle") => "idle_proud",
            (Demeanor::Nervous, "idle") => "idle_nervous",
            _ => base,
        };
        if model.clip(v).is_some() { v } else { base }
    };
    let stride = (1.75 / model_height.max(0.3)).sqrt().min(1.6);
    match posture.pose {
        Pose::Stand if posture.walking => {
            let w = variant("walk");
            let pace = match w {
                "walk_sad" => 0.8,
                "walk_proud" => 0.95,
                _ => 1.0,
            };
            (w, 1.1 * stride * pace * if stage == LifeStage::Elder { 0.85 } else { 1.0 })
        }
        Pose::Stand => (variant("idle"), 1.0),
        Pose::Sit => ("sit", 1.0),
        Pose::Lie => ("lie", 1.0),
        Pose::Use => ("use", 1.0),
        Pose::Dance => ("dance", 0.9),
        Pose::Exercise => ("exercise", 0.8),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_stage_model_loads_with_its_clips() {
        for (name, bytes) in FILES {
            let m = Model::load_glb(bytes, &slot_of).unwrap();
            let body = m.mesh("body").unwrap_or_else(|| panic!("{name}: body"));
            assert!(body.morph("slim").is_some() && body.morph("heavy").is_some(), "{name}: morphs");
            for s in [slot::SKIN, slot::SHIRT, slot::PANTS, slot::SHOES, slot::IRIS] {
                assert!(body.data.vertices.iter().any(|v| v.slot == s), "{name}: slot {s}");
            }
            for i in 0..HAIR_STYLES {
                assert!(m.mesh(&format!("hair{i}")).is_some(), "{name}: hair{i}");
            }
            for c in ["idle", "walk", "sit", "lie", "use", "dance", "exercise"] {
                assert!(m.clip(c).is_some(), "{name}: clip {c}");
            }
            let top = body.data.vertices.iter().map(|v| v.pos[1]).fold(0.0, f32::max);
            let want = LifeStage::ALL[match name {
                "infant" => 0,
                "toddler" => 1,
                "child" => 2,
                "teen" => 3,
                "adult" => 5,
                _ => 6,
            }]
            .height();
            assert!((top - want).abs() < want * 0.05, "{name}: model height {top}, stage height {want}");
        }
    }

    #[test]
    fn every_clip_the_data_names_exists_on_the_bodies_that_play_it() {
        let data = sim::data::GameData::embedded();
        for stage in LifeStage::ALL {
            let (name, bytes) = FILES[file_index(stage)];
            let moods: &[&str] = if stage.can_walk() { &["idle_sad", "walk_sad", "idle_proud", "walk_proud", "idle_nervous"] } else { &["idle_sad"] };
            let wanted: Vec<&str> = data.anims_for(stage).into_iter().chain(moods.iter().copied()).collect();
            let m = Model::load_glb(bytes, &slot_of).unwrap();
            let missing: Vec<_> = wanted.iter().filter(|c| m.clip(c).is_none()).collect();
            assert!(missing.is_empty(), "peon_{name}.glb ({stage:?}) lacks clips {missing:?}");
        }
    }

    #[test]
    fn interaction_clip_wins_and_falls_back_to_the_pose() {
        let m = adult();
        let mut p = Posture::performing(Pose::Use, Some("stir".into()), None);
        assert_eq!(clip_for(&m, LifeStage::Adult, &p, Demeanor::Normal, 1.75).0, "stir");
        p.anim = Some("no_such_clip".into());
        assert_eq!(clip_for(&m, LifeStage::Adult, &p, Demeanor::Normal, 1.75).0, "use");
        let walking = Posture { walking: true, ..Default::default() };
        assert_eq!(clip_for(&m, LifeStage::Adult, &walking, Demeanor::Sad, 1.75).0, "walk_sad");
    }

    #[test]
    fn grips_follow_the_hands() {
        let m = adult();
        let skel = &m.skeleton;
        let j = skel.joint("hand.R").unwrap();
        let off = grip_offset(skel, j, 1.75);
        let rest = skel.globals(&skel.rest_pose())[j] * off;
        // palm a little below and outside the wrist on the right (-x), grip z facing forward
        let wrist = skel.globals(&skel.rest_pose())[j].w_axis.truncate();
        let palm = rest.w_axis.truncate();
        assert!(palm.y < wrist.y && palm.x < wrist.x, "palm {palm} wrist {wrist}");
        assert!(rest.z_axis.truncate().dot(Vec3::Z) > 0.9);
    }

    fn adult() -> Model {
        Model::load_glb(FILES[4].1, &slot_of).unwrap()
    }

    fn hips_y(m: &Model, pose: &JointPose) -> f32 {
        m.skeleton.globals(pose)[m.skeleton.joint("hips").unwrap()].w_axis.y
    }

    #[test]
    fn clip_change_cross_fades_pose_and_root() {
        let m = adult();
        let mut a = AnimState::default();
        let floor = Vec3::new(2.0, 0.0, 2.0);
        let seat = Vec3::new(2.5, 0.45, 2.0);
        let mut t = 10.0;
        a.update(&m, 4, "idle", 1.0, t, floor, 0.0);
        let standing = hips_y(&m, &a.pose);

        // the sim snaps onto the seat as the posture changes: the first frame still looks standing
        t += 1.0 / 60.0;
        let (p, _) = a.update(&m, 4, "sit", 1.0, t, seat, 1.0);
        assert!((hips_y(&m, &a.pose) - standing).abs() < 0.02, "no pop into the sit pose");
        assert!(p.distance(floor) < 0.02, "root eased from where it was drawn: {p}");

        // halfway through the fade: in between
        t += BLEND_SECS * 0.5;
        let (p, _) = a.update(&m, 4, "sit", 1.0, t, seat, 1.0);
        let mut sitting = m.skeleton.rest_pose();
        m.clip("sit").unwrap().sample(t - 10.0, &mut sitting);
        let (mid, sat) = (hips_y(&m, &a.pose), hips_y(&m, &sitting));
        assert!(mid < standing - 0.05 && mid > sat + 0.05, "hips {mid} between {standing} and {sat}");
        assert!(p.distance(floor) > 0.1 && p.distance(seat) > 0.1, "root between: {p}");

        // after it: fully seated, root on the seat
        t += BLEND_SECS;
        let (p, yaw) = a.update(&m, 4, "sit", 1.0, t, seat, 1.0);
        let mut sitting = m.skeleton.rest_pose();
        m.clip("sit").unwrap().sample(a.phase, &mut sitting);
        assert_eq!(a.pose, sitting);
        assert_eq!((p, yaw), (seat, 1.0));
    }

    #[test]
    fn fresh_state_poses_from_the_clock_and_teleports_snap() {
        let m = adult();
        let mut a = AnimState::default();
        a.update(&m, 4, "walk", 1.3, 7.0, Vec3::ZERO, 0.0);
        let mut want = m.skeleton.rest_pose();
        m.clip("walk").unwrap().sample(7.0 * 1.3, &mut want);
        assert_eq!(a.pose, want);
        // coming home from across the map: the root jumps, not slides
        let far = Vec3::new(20.0, 0.0, 0.0);
        let (p, _) = a.update(&m, 4, "idle", 1.0, 7.02, far, 0.0);
        assert_eq!(p, far);
    }

    #[test]
    fn animator_forgets_peons_not_drawn() {
        let mut w = hearth_ecs::World::new();
        let (e1, e2) = (w.spawn_empty(), w.spawn_empty());
        let mut an = Animator::default();
        an.begin_frame();
        an.state(e1).phase = 1.0;
        an.state(e2).phase = 2.0;
        an.begin_frame();
        an.state(e1);
        an.begin_frame();
        assert_eq!(an.states.len(), 1);
        assert_eq!(an.state(e1).phase, 1.0);
        assert_eq!(an.state(e2).phase, 0.0);
    }
}
